#!/usr/bin/env node

// Copy the immutable design reference into production assets without hand-editing it, and derive the
// three stylesheets the page loads from it and production.css. Run from anywhere (after an edit to the
// demo or to production.css); paths are resolved from this script. The generated files are tracked.
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { deriveStylesheets } from "./session-view-css.mjs";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const sourcePath = resolve(root, "design/agent-monitor-codex-demo.html");
const out = resolve(root, "claude-monitor/src/codex-ui");
const source = await readFile(sourcePath, "utf8");

function between(start, end) {
  const from = source.indexOf(start);
  const to = source.indexOf(end, from + start.length);
  if (from < 0 || to < 0) throw new Error(`reference marker missing: ${start} … ${end}`);
  return source.slice(from + start.length, to);
}

const css = between("<style>\n", "\n</style>") + "\n";
const shell = between("<body>\n", '<script src="sample-transcript-data.js"></script>');
const iconStart = source.indexOf("const icons=");
const iconEnd = source.indexOf("const shared={};", iconStart);
if (iconStart < 0 || iconEnd < 0) throw new Error("reference icon registry markers missing");
let icons = source.slice(iconStart, iconEnd);
icons = icons.replace(/document\.querySelectorAll\([\s\S]*?function agentLogo/, "function agentLogo");
icons += "\nexport { icons, svg, agentLogo };\n";

// The session view's markup (#s429, design/session-view-component.md, stage 4): the workspace, the
// pane's resizer and the artifact pane, one block of the shell. The view builds itself from it
// (`session-view-markup.js`), and the page the monitor serves is the shell with an empty
// `#sessionView` in its place (`app-shell.html`). Both are cut from the shell, never edited.
const viewStart = shell.indexOf('  <main class="workspace">');
const previewStart = shell.indexOf('  <aside class="preview" id="preview"', viewStart);
const viewEnd = shell.indexOf("\n  </aside>\n", previewStart) + "\n  </aside>\n".length;
if (viewStart < 0 || previewStart < 0 || viewEnd < previewStart) throw new Error("the session view's markup markers are missing from the shell");
const viewMarkup = shell.slice(viewStart, viewEnd);
let appShell = `${shell.slice(0, viewStart)}  <div class="session-view preview-off" id="sessionView"></div>\n${shell.slice(viewEnd)}`;
const markupModule = `// Generated by scripts/extract-agent-monitor-demo.mjs from design/agent-monitor-codex-demo.html: the
// session view's markup, which mountSessionView builds itself from (#s429 stage 4). Never hand-edit.
export const SESSION_VIEW_MARKUP = ${JSON.stringify(viewMarkup)};
`;

// The session list's markup (#s430, design/session-list-component.md, stage 3): the parts of the
// sidebar the list draws, cut from where the shell has them. Collapse all from the head's row, the
// agent marks' holder from the rail and the tree, in that order; the list builds itself from them
// (`session-list-markup.js`) and places the first two back through its host. The tree's line becomes
// an empty `#sessionList`, the list's element. The demo's two attention controls (the Needs attention
// button and the rail's bell), which the list removed as it mounted, are cut and kept nowhere. Each
// piece must be in the shell exactly once.
const LIST_CUTS = Object.freeze([
  { name: "collapse", from: '<button class="iconbtn" id="collapseBtn"', to: "</button>", keep: true },
  { name: "marks", from: '<div class="sidebar-mini-agents" id="sidebarMiniAgents"', to: "</div>", keep: true },
  { name: "tree", from: '    <div class="tree" id="tree"', to: "</div>\n", keep: true, placeholder: '    <div class="session-list" id="sessionList"></div>\n' },
  { name: "attention-mini", from: '<button class="sidebar-mini-button attention-mini" id="sidebarMiniAttention"', to: "</span></button>", keep: false },
  { name: "attention", from: '      <button class="navbtn attention-filter" id="attentionBtn"', to: "</span></button>\n", keep: false },
]);
/** Cut the list's pieces from `text`: the shell left, and the kept pieces' markup in their order. */
function cutList(text) {
  let rest = text;
  const kept = [];
  for (const cut of LIST_CUTS) {
    const at = rest.indexOf(cut.from);
    if (at < 0 || rest.indexOf(cut.from, at + 1) >= 0) throw new Error(`the session list's piece \`${cut.name}\` is not in the shell exactly once`);
    const end = rest.indexOf(cut.to, at) + cut.to.length;
    const piece = rest.slice(at, end);
    if (cut.keep) kept.push(piece.trim());
    rest = `${rest.slice(0, at)}${cut.placeholder || ""}${rest.slice(end)}`;
  }
  return { shell: rest, markup: kept.join("\n") };
}
const list = cutList(appShell);
appShell = list.shell;
const listModule = `// Generated by scripts/extract-agent-monitor-demo.mjs from design/agent-monitor-codex-demo.html: the
// session list's markup (Collapse all, the agent marks' holder and the tree), which mountSessionList
// builds itself from (#s430 stage 3). Never hand-edit.
export const SESSION_LIST_MARKUP = ${JSON.stringify(list.markup)};
`;

await mkdir(out, { recursive: true });
await writeFile(resolve(out, "reference.css"), css);
await writeFile(resolve(out, "reference-shell.html"), shell);
await writeFile(resolve(out, "app-shell.html"), appShell);
await writeFile(resolve(out, "session-view-markup.js"), markupModule);
await writeFile(resolve(out, "session-list-markup.js"), listModule);
await writeFile(resolve(out, "icons.js"), icons);

// The session view's stylesheet, the session list's and the app's (#s429 stage 5b, #s430 stage 3),
// derived from reference.css and production.css, which stay the sources: every rule of the view's
// hangs on its element, every rule of the list's on its own, and the app's chrome and the page keep
// the rest (`session-view-css.mjs` says how it decides).
const production = await readFile(resolve(out, "production.css"), "utf8");
const styles = deriveStylesheets({ reference: css, production });
// The demo names the tree as the sidebar's child twice (`.sidebar>.tree`, and under `sidebar-off`),
// and the app's file sends both through the list's element (#s430 stage 3). A third is a new rule to
// read; production.css writes its own through `:where(.session-list)` already.
if (styles.report.listChild.length !== 2) throw new Error(`app-shell.css: ${styles.report.listChild.length} selectors name the tree as the sidebar's child, where the demo had two: ${styles.report.listChild.join(", ")}`);
await writeFile(resolve(out, "session-view.css"), styles.view);
await writeFile(resolve(out, "session-list.css"), styles.list);
await writeFile(resolve(out, "app-shell.css"), styles.app);
